import fs from 'node:fs';
import cp from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { syncBuiltinESMExports } from 'node:module';
import { AsyncLocalStorage } from 'node:async_hooks';

const directory = path.dirname(fileURLToPath(import.meta.url));
const output = path.join(directory, 'events', `${process.pid}.jsonl`);
const append = fs.appendFileSync;
const als = new AsyncLocalStorage();
const file = process.argv.slice(1).find(value => /\.(?:test|contract)\.ts$/.test(value));
if (file) process.env.DR_PROFILE_FILE = file.replaceAll('\\', '/').replace(/^.*\/(test\/)/, '$1');
const context = process.env.DR_PROFILE_FILE ?? null;
const epoch = performance.timeOrigin;
let sequence = 0;
function emit(value) {
  try { append(output, `${JSON.stringify({ pid: process.pid, context, at: epoch + performance.now(), scope: als.getStore() ?? null, ...value })}\n`); } catch {}
}
function location() {
  return (new Error().stack ?? '').split('\n').filter(line => /\/(?:src|test|scripts)\//.test(line) && !line.includes('preload.mjs')).slice(0, 2).map(line => line.trim().replace(/^.*\/(?=(?:src|test|scripts)\/)/, ''));
}
const gitCommands = new Set(['add','am','apply','branch','cat-file','check-attr','check-ignore','checkout','clone','commit','commit-tree','config','diff','diff-files','diff-index','for-each-ref','hash-object','init','log','ls-files','ls-tree','merge','merge-base','mv','read-tree','reset','rev-parse','rm','show','show-ref','status','symbolic-ref','update-index','update-ref','version','worktree','write-tree']);
function category(command, args) {
  const name = path.basename(String(command)).toLowerCase().replace(/\.exe$/, '');
  if (name === 'git') return `git:${args.find(arg => gitCommands.has(String(arg))) ?? 'other'}`;
  if (name === 'node' || command === process.execPath) {
    const entry = args.find(arg => /(?:\.ts|\.mjs|\.js|\.cjs)$/.test(String(arg))) ?? '';
    if (/fake[-/]?claude/.test(entry)) return args.includes('--version') ? 'node:fake-runtime-probe' : 'node:fake-claude';
    if (/fake[-/]?codex/.test(entry)) return args.includes('--version') ? 'node:fake-runtime-probe' : 'node:fake-codex';
    if (/fake[-/]?check/.test(entry)) return 'node:fake-check';
    if (/fake[-/]?gh/.test(entry)) return 'node:fake-gh';
    if (/fake[-/]?(?:hanging-)?probe/.test(entry)) return 'node:fake-probe';
    for (const verb of ['guard','claim','snapshot','review','commit','publish','answer','report','config','status']) if (args.includes(verb)) return `node:cli-${verb}`;
    if (args.includes('--test')) return 'node:test-runner';
    return 'node:other';
  }
  if (name === 'sh' || name === 'bash' || name === 'cmd') return args.some(arg => String(arg).includes('fake-check')) ? 'shell:fake-check' : 'shell:other';
  return `other:${name}`;
}
for (const method of ['spawn','spawnSync','execFileSync']) {
  const original = cp[method];
  cp[method] = function(command, ...rest) {
    const args = Array.isArray(rest[0]) ? rest[0] : [];
    const kind = category(command, args);
    const id = `${process.pid}:${++sequence}`;
    const start = performance.now();
    const caller = location();
    emit({ type: 'child-start', id, method, kind, caller });
    try {
      const result = original.call(this, command, ...rest);
      if (method === 'spawn') {
        emit({ type: 'child-pid', id, childPid: result.pid ?? null });
        result.once('close', (code, signal) => emit({ type: 'child-end', id, kind, elapsedMs: performance.now() - start, code, signal, childPid: result.pid ?? null }));
      } else emit({ type: 'child-end', id, kind, elapsedMs: performance.now() - start, code: method === 'spawnSync' ? result.status : 0, signal: method === 'spawnSync' ? result.signal : null });
      return result;
    } catch (error) {
      emit({ type: 'child-end', id, kind, elapsedMs: performance.now() - start, code: error.status ?? null, signal: error.signal ?? null, threw: true });
      throw error;
    }
  };
}
for (const name of ['cpSync','rmSync','mkdtempSync']) {
  const original = fs[name];
  fs[name] = function(...args) {
    const start = performance.now();
    try { return original.apply(this, args); }
    finally { emit({ type: 'filesystem', kind: name, elapsedMs: performance.now() - start, caller: location() }); }
  };
}
syncBuiltinESMExports();
const timeout = globalThis.setTimeout;
globalThis.setTimeout = function(callback, delay, ...args) {
  if (typeof callback !== 'function') return timeout(callback, delay, ...args);
  const start = performance.now();
  const caller = location();
  const scope = als.getStore() ?? null;
  return timeout(function(...values) {
    emit({ type: 'timer-completed', requestedMs: Number(delay) || 0, elapsedMs: performance.now() - start, caller, scope });
    return callback.apply(this, values);
  }, delay, ...args);
};
globalThis[Symbol.for('deep-review.profile')] = {
  async span(kind, detail, action) {
    const start = performance.now();
    const id = `${process.pid}:span:${++sequence}`;
    emit({ type: 'span-start', id, kind, detail });
    return als.run({ kind, ...detail }, async () => {
      try { return await action(); }
      finally { emit({ type: 'span-end', id, kind, detail, elapsedMs: performance.now() - start }); }
    });
  },
  duration(kind, start) { emit({ type: 'setup', kind, elapsedMs: performance.now() - start }); },
};
emit({ type: 'process-start', ppid: process.ppid, role: file ? 'node:test-file' : category(process.execPath, process.argv.slice(1)) });
